<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useCart } from '../stores/cart'
import { money, type CartItem } from '../types'
import ProductArt from '../components/ProductArt.vue'
const cart = useCart(), quantities = ref<Record<string, number>>({}), confirmClear = ref(false)
async function reload() { try { await cart.load(); quantities.value = {} } catch { /* The cart store displays the error. */ } }
async function update(item: CartItem) { try { await cart.setQuantity(item.productId, quantities.value[item.productId] ?? item.quantity); quantities.value = {} } catch { /* The cart store displays the error. */ } }
async function remove(id: string) { try { await cart.remove(id) } catch { /* The cart store displays the error. */ } }
async function empty() { try { await cart.empty(); confirmClear.value = false } catch { /* The cart store displays the error. */ } }
onMounted(reload)
</script>
<template><section class="section"><div class="section-heading"><div><p class="eyebrow">YOUR NEXT ADVENTURES</p><h1>Your cart<span class="accent">.</span></h1></div><RouterLink class="back-link" to="/">Continue browsing →</RouterLink></div><p class="muted">Saved to your account. Prices and availability are checked against the current catalog.</p><div v-if="cart.error" class="error" role="alert">{{ cart.error }} <button class="text-button" :disabled="cart.busy" @click="reload">Reload cart</button></div><p v-if="cart.loading" role="status">Loading cart…</p><template v-else-if="cart.cart"><div v-if="!cart.cart.items.length" class="empty"><h2>Your cart is waiting.</h2><p>Find something for your next gaming session.</p><RouterLink class="button" to="/">Explore the collection</RouterLink></div><div v-else class="cart-layout"><div><article v-for="item in cart.cart.items" :key="item.productId" class="cart-row"><ProductArt :name="item.name" :image-url="item.imageUrl" /><div><RouterLink v-if="item.isActive" :to="`/products/${item.productId}`"><h3>{{ item.name }}</h3></RouterLink><h3 v-else>{{ item.name }}</h3><p>{{ money(item.price) }} each</p><p v-if="!item.isActive || item.stock < item.quantity" class="danger-text">{{ !item.isActive ? 'No longer available. Please remove this item.' : `Only ${item.stock} in stock. Adjust the quantity or remove it.` }}</p><form class="actions" @submit.prevent="update(item)"><label>Quantity<span class="sr-only"> for {{ item.name }}</span><input :value="quantities[item.productId] ?? item.quantity" @input="quantities[item.productId] = Number(($event.target as HTMLInputElement).value)" type="number" required min="1" :max="Math.min(99, item.stock)" step="1" :disabled="cart.busy || !item.isActive || item.stock === 0"></label><button class="button secondary small" type="submit" :disabled="cart.busy || !item.isActive || item.stock === 0">Update<span class="sr-only"> {{ item.name }}</span></button><button type="button" class="text-button" :disabled="cart.busy" @click="remove(item.productId)">Remove<span class="sr-only"> {{ item.name }}</span></button></form></div><strong>{{ money(item.lineTotal) }}</strong></article></div><aside class="panel cart-summary"><h2>Summary</h2><p>{{ cart.cart.totalQuantity }} items</p><div class="cart-total"><span>Total</span><strong>{{ money(cart.cart.total) }}</strong></div><p class="muted">Cart total only. Stock is not reserved. Checkout and payments are not available yet.</p><button v-if="!confirmClear" class="text-button" :disabled="cart.busy" @click="confirmClear = true">Empty cart</button><div v-else><p>Remove all items?</p><div class="actions"><button class="button secondary small" :disabled="cart.busy" @click="empty">Yes, empty cart</button><button class="text-button" :disabled="cart.busy" @click="confirmClear = false">Cancel</button></div></div></aside></div></template></section></template>
